package pl.crimeandlaw.cultivation;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class PlanterStateTest {
    private PlanterState planted(boolean seedling){var s=new PlanterState();assertTrue(s.fillSoil());assertTrue(s.plant(seedling));s.addWater(100);return s;}
    private void grow(PlanterState s,boolean lamp,int value){for(int i=0;i<18001&&!s.mature();i++)s.step(true,lamp,b->value);assertTrue(s.mature());}
    @Test void emptyPotCannotGrowAndMaterialsAreSingleUse(){var s=new PlanterState();assertFalse(s.plant(false));assertEquals(0,s.addWater(100));assertTrue(s.fillSoil());assertFalse(s.fillSoil());assertTrue(s.plant(false));assertFalse(s.plant(true));assertFalse(s.step(true,true,b->0));assertEquals(2,s.stage());}
    @Test void darknessAndDroughtPauseGrowthWithoutRerolls(){var s=planted(false);var calls=new AtomicInteger();for(int i=0;i<10000;i++)assertFalse(s.step(false,true,b->{calls.incrementAndGet();return 0;}));assertEquals(0,s.growth());assertEquals(100,s.water());assertEquals(0,calls.get());}
    @Test void oneRollSurvivesRestoresAndRepeatedScreens(){var s=planted(false);var calls=new AtomicInteger();for(int i=0;i<18000;i++)s.step(true,true,b->{assertEquals(5,b);calls.incrementAndGet();return 4;});assertEquals(8,s.total());assertEquals(255,s.leaves());assertEquals(1,calls.get());var id=s.identity();var copy=new PlanterState();copy.restore(s.data());for(int i=0;i<1000;i++)assertFalse(copy.step(true,true,b->{calls.incrementAndGet();return 0;}));assertEquals(id,copy.identity());assertEquals(8,copy.total());assertEquals(1,calls.get());}
    @Test void ordinaryAndUvBoundsAreInclusive(){for(boolean uv:new boolean[]{false,true})for(int roll=0;roll<(uv?5:4);roll++){var s=planted(false);grow(s,uv,roll);assertEquals((uv?4:3)+roll,s.total());assertEquals(s.total(),PruningRules.count(s.leaves()));}}
    @Test void lampAddedAtHarvestDoesNotGetFullBonus(){var s=planted(false);for(int i=0;i<17999;i++)s.step(true,false,b->0);s.step(true,true,b->{assertEquals(4,b);return 3;});assertEquals(6,s.total());}
    @Test void exactEightyPercentExposureBoundary(){assertFalse(CultivationRules.uvEligible(0,0));assertFalse(CultivationRules.uvEligible(79,100));assertTrue(CultivationRules.uvEligible(80,100));assertTrue(CultivationRules.uvEligible(Integer.MAX_VALUE,Integer.MAX_VALUE));for(int lampTicks:new int[]{14399,14400}){var s=planted(false);for(int i=0;i<18000;i++)s.step(true,i<lampTicks,b->{assertEquals(lampTicks==14400?5:4,b);return b-1;});assertEquals(lampTicks==14400?8:6,s.total());}}
    @Test void seedlingUsesItsActualGrowthIntervalForExposure(){var s=planted(true);assertEquals(3600,s.growth());grow(s,true,4);assertEquals(8,s.total());assertEquals(20,s.water());}
    @Test void waterIsFiniteAndRefillDoesNotOverflow(){var s=planted(false);for(int i=0;i<180;i++)s.step(true,false,b->0);assertEquals(99,s.water());assertEquals(1,s.addWater(Integer.MAX_VALUE));assertEquals(0,s.addWater(400));assertEquals(0,s.addWater(-1));}
    @Test void everyLeafPaysOnceAndCycleConsumesSoil(){var s=planted(false);grow(s,true,4);UUID old=s.identity();for(int id:new int[]{7,2,5,0,6,1,4,3}){assertTrue(s.cut(id));assertFalse(s.cut(id));}assertTrue(s.finish());assertFalse(s.finish());assertEquals(0,s.stage());assertFalse(s.soil());assertFalse(s.planted());assertEquals(0,s.water());assertNotEquals(old,s.identity());assertFalse(s.plant(false));}
    @Test void partialHarvestRetainsExactMaskAndIdentity(){var s=planted(false);grow(s,true,4);s.cut(7);s.cut(1);var p=new PlanterState();p.restore(s.data());assertEquals(s.data(),p.data());assertFalse(p.cut(7));assertTrue(p.cut(6));assertFalse(p.finish());}
    @Test void exhaustedSavedCropFinishesInsteadOfRegrowing(){var s=planted(false);grow(s,false,0);for(int i=0;i<3;i++)s.cut(i);var p=new PlanterState();p.restore(s.data());assertEquals(0,p.stage());assertFalse(p.soil());}
    @Test void malformedSaveCannotCreateWaterOrLeavesWithoutSoil(){var s=new PlanterState();s.restore(new PlanterState.Data(false,true,Integer.MAX_VALUE,Integer.MIN_VALUE,Integer.MAX_VALUE,Integer.MAX_VALUE,8,255,null));assertEquals(0,s.stage());assertEquals(0,s.total());assertEquals(0,s.water());assertEquals(0,s.growth());}
    @Test void durationBoundsRejectOverflowAndEarlyLateCompletion(){for(long held:new long[]{Long.MIN_VALUE,-1,0,59,1801,Long.MAX_VALUE})assertFalse(CultivationRules.validHold(1,held));assertTrue(CultivationRules.validHold(1,60));assertTrue(CultivationRules.validHold(1,1800));assertTrue(CultivationRules.validHold(2,30));assertTrue(CultivationRules.validHold(2,1800));assertFalse(CultivationRules.validHold(3,100));}
}
